                                # Explicit refusal precedes vague-date follow-up and generic question handlers.
                                touched = True
                                if p['status'] == 'excluded':
                                    continue
                                p['refused'].append(signature(p))
                                p.update(status='open',confirmed='',pending_kind='',pending_text='',date_conflict=False)
                                if p.get('hardship') or hardship_now:
                                    exclude(i,'hardship')
                                elif phase == 'all_today' and s['mode'] == 'B':
                                    s['sequential'] = True
                                elif phase == 'confirm':
                                    pass
                                elif i == s.get('active',0):
                                    persuade(i)
                            elif p.get('offer_kind') == 'exact_date' and not t.get('turn_question'):
                                touched = True
                                p['date'] = p['deadline']
                                queue_offer(i,'deadline','The latest date I can record for your ' + p['label'] + ' is ' + spoken_date(p['deadline']) + '. Can you pay ' + str(p['amount']) + ' then?')
                            elif not t.get('turn_question') and not tags.intersection({'ai','scam','discount','unknown'}) and phase != 'resolve_product':
                                touched = True
                                if p['status'] == 'excluded':
                                    continue
                                p['refused'].append(signature(p))
                                p.update(status='open',confirmed='',pending_kind='',pending_text='',date_conflict=False)
                                if p.get('hardship') or hardship_now:
                                    exclude(i,'hardship')
                                elif phase == 'all_today' and s['mode'] == 'B':
                                    s['sequential'] = True
                                elif phase != 'confirm' and i == s.get('active',0):
                                    persuade(i)
                    if touched or phase == 'resolve_product':
                        if s['mode'] == 'A' and ps and ps[0]['status'] == 'excluded':
                            r = ps[0]['reason']
                            finish('paid' if r == 'paid' else 'no_promise','' if r == 'paid' else r)
                        else:
                            progress()
                    elif phase == 'post_record':
                        finish()
                    else:
                        speak(vars.get('last_core_message','Please clarify your response.'),phase,vars.get('last_offer',''))
        else:
            speak('I can explain more after the security check.',phase,vars.get('last_offer',''))
        if 'no_talk' in tags and not s.get('terminal'):
            s['no_talk'] = s.get('no_talk',0)+1
    s['products'] = ps
    vars['state'] = json.dumps(s)
    vars['phase'] = s['phase']
    if vars['route'] == 'dialogue':
        vars['last_message'] = vars['message']
        vars['last_offer'] = vars['pending_offer']
except Exception:
    try:
        s['products'] = ps
        s['notices'].append('I could not complete this operation. Please use the mobile app or contact Freya Bank.')
        for p in ps:
            if p.get('status') != 'recorded' and not p.get('reason'):
                p.update(status='excluded',reason='service_error',confirmed='')
        finish('no_promise' if s.get('verified') else 'not_verified','service_error' if s.get('verified') else 'declined')
        vars['state'] = json.dumps(s)
        vars['phase'] = s['phase']
    except Exception:
        vars['outcome'],vars['reason'] = 'not_reached','unclear'
        vars['farewell'] = 'I could not complete this operation. Thank you. Goodbye.'
        vars['route'] = 'farewell'

